#!/usr/bin/env python3
# Remplace le logo Eden de l'ecran de demarrage (et de l'ecran "A propos") par le logo DEN.
# Lance depuis la racine du depot :  python3 apply_splash.py
import base64, os
if os.path.exists(".nextendo_splash_applied"):
    raise SystemExit("deja applique")
res = "src/android/app/src/main/res/"
for f in ("drawable/ic_yuzu_splash.png", "drawable/ic_yuzu.png", "values/themes.xml"):
    if not os.path.exists(res + f):
        raise SystemExit("FICHIER INTROUVABLE : " + res + f)

SPLASH = ""
LOGO = ""

open(res + "drawable/ic_yuzu_splash.png", "wb").write(base64.b64decode(SPLASH))
open(res + "drawable/ic_yuzu.png", "wb").write(base64.b64decode(LOGO))

p = res + "values/themes.xml"
s = open(p, encoding="utf-8").read()
a = '<item name="windowSplashScreenBackground">@color/eden_background</item>'
if s.count(a) != 1:
    raise SystemExit("ANCRE INTROUVABLE (themes.xml): trouve %d" % s.count(a))
s = s.replace(a, '<item name="windowSplashScreenBackground">@color/ic_launcher_background</item>')
open(p, "w", encoding="utf-8", newline="\n").write(s)

open(".nextendo_splash_applied", "w").write("ok\n")
print("OK : ecran de demarrage DEN")
